def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full line of 2s is the wall; objects slide as rigid 4-connected pieces
    # toward that wall (upward if wall is at the top, downward if at the bottom).
    wall_row = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    direction = 1 if wall_row == 0 else -1
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 2) or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            pieces.append((color, cells))
    # Simulate simultaneous one-cell gravity steps until all pieces are blocked.
    positions = [set(cells) for _, cells in pieces]
    while True:
        occupied = set().union(*positions) if positions else set()
        movable = []
        for i, cells in enumerate(positions):
            target = {(r + direction, c) for r, c in cells}
            can = all(0 <= r < h and 0 <= c < w and (r, c) not in occupied and grid[r][c] != 2 for r, c in target)
            movable.append(can)
        if not any(movable):
            break
        # Determine movement against the pre-step occupancy, allowing simultaneous moves.
        for i, can in enumerate(movable):
            if can:
                positions[i] = {(r + direction, c) for r, c in positions[i]}
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                out[r][c] = 2
    for (color, _), cells in zip(pieces, positions):
        for r, c in cells:
            out[r][c] = color
    return out

